<script setup lang="ts">
import {computed} from 'vue'
import type {AuthorValue,PlotEnding} from './types'
import PlotCheckEditor from './PlotCheckEditor.vue'
import {plotId,plotCheck} from './plot-utils'
const props=defineProps<{value:AuthorValue}>(),people=computed(()=>props.value.definition.entities.filter(e=>e.type==='character')),places=computed(()=>props.value.definition.entities.filter(e=>e.type==='place')),items=computed(()=>props.value.definition.entities.filter(e=>e.type==='item'))
const objectives=computed(()=>props.value.plot?.objectives||[])
function objective(){return {id:plotId('objective'),title:'新的任务',description:'说明玩家需要实际完成的事。',requires:[],checks:[plotCheck()],sourceBlockIds:['AUTHOR-CONFIG']}}
function ending():PlotEnding{return {...objective(),id:plotId('ending'),title:'新的结局',requires:objectives.value.length?[objectives.value.at(-1)!.id]:[],selectionDescription:'玩家作出这个选择后，继续完成善后。',settlementSteps:[],transitions:[]}}
function create(){const actor=people.value[0],place=places.value[0];if(!actor||!place)return;props.value.plot={synopsis:props.value.summary,recommendedCharacterId:actor.id,opening:props.value.openings[0]?.text||'观察眼前的情况。',conservedItemIds:[],scenes:[{id:plotId('scene'),title:'开场场景',summary:props.value.summary,placeId:place.id,characterIds:people.value.map(p=>p.id),sourceBlockIds:['AUTHOR-CONFIG']}],objectives:[],endings:[]};props.value.plot.objectives.push(objective());props.value.plot.endings.push(ending())}
function step(e:PlotEnding){e.settlementSteps.push({...objective(),id:plotId('step'),title:'新的善后步骤',origin:'adaptation',sourceBlockIds:[],completionClaims:[]})}
function transition(e:PlotEnding){const id=plotId('transition');e.transitions.push({id,title:'新的办理操作',authorityId:people.value[0]?.id||'',placeId:places.value[0]?.id||'',actionTerms:['申请办理'],requires:[],checks:[plotCheck()],effects:[{entityId:people.value[0]?.id||'',field:'field:author_aftercare',value:'已办理'}],minMinutes:1,origin:'adaptation',sourceBlockIds:[]});e.settlementSteps.push({...objective(),id:plotId('step'),title:'确认办理回执',origin:'adaptation',sourceBlockIds:[],completionClaims:[],checks:[{...plotCheck(),kind:'transition',value:id}]})}
</script>
<template><section class="author-plot-editor"><h2>任务、结局与善后</h2><p>任务按实际状态验收。到达不等于交接，批准不等于亲自办理。新改编规则只用于新开局，已有存档保留原定义。</p><button v-if="!value.plot" :disabled="!people.length||!places.length" @click="create">添加剧情与结局规则</button><template v-else><label>剧情说明<textarea v-model="value.plot.synopsis" maxlength="1500"></textarea></label><label>推荐主角<select v-model="value.plot.recommendedCharacterId"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>规则开场<textarea v-model="value.plot.opening" maxlength="1200"></textarea></label><label>唯一物证（多选，必须有一个初始持有人）<select multiple v-model="value.plot.conservedItemIds"><option v-for="p in items" :key="p.id" :value="p.id">{{p.name}}</option></select></label><h3>场景安排</h3><article v-for="(scene,i) in value.plot.scenes" :key="scene.id" class="author-item"><label>场景名称<input v-model="scene.title" maxlength="120"></label><label>场景描述<textarea v-model="scene.summary" maxlength="800"></textarea></label><label>场景地点<select v-model="scene.placeId"><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>登场人物<select multiple v-model="scene.characterIds"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button :disabled="value.plot.scenes.length===1" @click="value.plot.scenes.splice(i,1)">删除场景</button></article><button :disabled="value.plot.scenes.length>=40" @click="value.plot.scenes.push({id:plotId('scene'),title:'新的场景',summary:'描述这个场景。',placeId:places[0]?.id||'',characterIds:[],sourceBlockIds:['AUTHOR-CONFIG']})">添加场景</button><h3>调查任务</h3><article v-for="(o,i) in value.plot.objectives" :key="o.id" class="author-item"><h4>任务 {{i+1}}</h4><label>任务名称<input v-model="o.title" maxlength="120"></label><label>任务说明<textarea v-model="o.description" maxlength="600"></textarea></label><label>前置任务<select multiple v-model="o.requires"><option v-for="r in objectives.filter(r=>r.id!==o.id)" :key="r.id" :value="r.id">{{r.title}}</option></select></label><div v-for="(check,j) in o.checks" :key="j"><PlotCheckEditor :check="check" :value="value"/><button :disabled="o.checks.length===1" @click="o.checks.splice(j,1)">删除此条件</button></div><button :disabled="o.checks.length>=8" @click="o.checks.push(plotCheck())">添加验收条件</button><button :disabled="objectives.length===1" @click="objectives.splice(i,1)">删除任务</button></article><button :disabled="objectives.length>=16" @click="objectives.push(objective())">添加任务</button><h3>结局与善后</h3><article v-for="(e,i) in value.plot.endings" :key="e.id" class="author-item"><label>结局名称<input v-model="e.title" maxlength="160"></label><label>结局说明<textarea v-model="e.description" maxlength="800"></textarea></label><label>选择后的提示<textarea v-model="e.selectionDescription" maxlength="800"></textarea></label><label>必须完成的任务<select multiple v-model="e.requires"><option v-for="o in objectives" :key="o.id" :value="o.id">{{o.title}}</option></select></label><h4>结局选择条件</h4><div v-for="(check,j) in e.checks" :key="j"><PlotCheckEditor :check="check" :value="value" :ending="true"/><button @click="e.checks.splice(j,1)">删除选择条件</button></div><button :disabled="e.checks.length>=8" @click="e.checks.push(plotCheck())">添加选择条件</button><details v-for="(s,j) in e.settlementSteps" :key="s.id" open><summary>善后 {{j+1}}：{{s.title}}</summary><label>步骤名称<input v-model="s.title" maxlength="120"></label><label>步骤说明<textarea v-model="s.description" maxlength="600"></textarea></label><label>前置善后<select multiple v-model="s.requires"><option v-for="r in e.settlementSteps.filter(r=>r.id!==s.id)" :key="r.id" :value="r.id">{{r.title}}</option></select></label><div v-for="(check,k) in s.checks" :key="k"><PlotCheckEditor :check="check" :value="value" :transitions="e.transitions"/><button :disabled="s.checks.length===1" @click="s.checks.splice(k,1)">删除善后条件</button></div><button :disabled="s.checks.length>=8" @click="s.checks.push(plotCheck())">添加善后条件</button><button @click="e.settlementSteps.splice(j,1)">删除善后步骤</button></details><details v-for="(t,j) in e.transitions" :key="t.id"><summary>办理操作：{{t.title}}</summary><label>操作名称<input v-model="t.title" maxlength="120"></label><label>批准者<select v-model="t.authorityId"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>办理地点<select v-model="t.placeId"><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>触发语句（逗号分隔）<input :value="t.actionTerms.join('，')" @change="t.actionTerms=($event.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)"></label><label>前置善后<select multiple v-model="t.requires"><option v-for="s in e.settlementSteps" :key="s.id" :value="s.id">{{s.title}}</option></select></label><label>最少经过分钟<input v-model.number="t.minMinutes" type="number" min="1" max="1440"></label><div v-for="(check,k) in t.checks" :key="k"><PlotCheckEditor :check="check" :value="value" :transitions="e.transitions"/><button :disabled="t.checks.length===1" @click="t.checks.splice(k,1)">删除办理条件</button></div><button :disabled="t.checks.length>=8" @click="t.checks.push(plotCheck())">添加办理条件</button><div v-for="(effect,k) in t.effects" :key="k" class="author-columns"><label>结果人物<select v-model="effect.entityId"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>结果字段<input v-model="effect.field" placeholder="field:author_aftercare 或 location"></label><label>结果值<input v-if="typeof effect.value==='string'" v-model="effect.value"><input v-else-if="typeof effect.value==='number'" v-model.number="effect.value" type="number"><select v-else v-model="effect.value"><option :value="true">是</option><option :value="false">否</option></select></label><button :disabled="t.effects.length===1" @click="t.effects.splice(k,1)">删除结果</button></div><button :disabled="t.effects.length>=8" @click="t.effects.push({entityId:people[0]?.id||'',field:'field:author_aftercare',value:'已办理'})">添加办理结果</button><button @click="e.transitions.splice(j,1)">删除办理操作</button></details><button :disabled="e.settlementSteps.length>=12" @click="step(e)">添加善后步骤</button><button :disabled="e.transitions.length>=12||e.settlementSteps.length>=12" @click="transition(e)">添加办理操作与回执</button><button :disabled="value.plot.endings.length===1" @click="value.plot.endings.splice(i,1)">删除结局</button></article><button :disabled="value.plot.endings.length>=5" @click="value.plot.endings.push(ending())">添加结局</button></template></section></template>
<style scoped>.author-plot-editor label{display:block;margin:14px 0}.author-plot-editor input,.author-plot-editor textarea,.author-plot-editor select{width:100%;min-height:44px}.author-plot-editor button{min-height:44px;margin:6px 8px 6px 0}.author-plot-editor details{padding:14px;margin:14px 0;border:1px solid var(--border,#e8e1d8);border-radius:12px}.author-plot-editor summary{min-height:44px;cursor:pointer}.author-plot-editor select[multiple]{min-height:88px}</style>
